import { createHash } from "node:crypto";
import { mkdir, readFile, readdir, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { loadScenarioPacks, resolveScenarioManifest, scenarioRootsFromArgv } from "./scenario-pack.mjs";

const repo = resolve(import.meta.dirname, "../..");
const domains = ["characters", "skills", "enemies", "encounters", "world", "factions", "sites", "production", "diplomacy", "ai_scenarios", "campaign", "weather", "presentation"];
const records = [];

for (const domain of domains) {
  const directory = resolve(repo, "content", domain);
  for (const filename of (await readdir(directory)).filter(name => name.endsWith(".json")).sort()) {
    const sourcePath = `content/${domain}/${filename}`;
    const value = JSON.parse(await readFile(resolve(directory, filename), "utf8"));
    records.push({ domain, id: value.id, sourcePath, value });
  }
}

records.sort((left, right) => left.id.localeCompare(right.id));
const canonicalRecords = JSON.stringify(records);
const bundle = {
  format: "project42.content_bundle",
  version: 1,
  generatedFrom: "validated source JSON; do not edit this file by hand",
  recordCount: records.length,
  contentHash: `sha256:${createHash("sha256").update(canonicalRecords).digest("hex")}`,
  records
};

const outputDirectory = resolve(repo, "game/generated");
await mkdir(outputDirectory, { recursive: true });
await writeFile(resolve(outputDirectory, "content_bundle.json"), `${JSON.stringify(bundle, null, 2)}\n`, "utf8");
console.log(`Built Godot content bundle with ${records.length} records (${bundle.contentHash}).`);

// Scenario packs (docs/SCENARIO_PACKS.md): one generated document per pack, with
// every referenced document embedded verbatim. Run the validator first; this
// builder embeds what the validator has already proved.
const scenarioRoots = scenarioRootsFromArgv(repo, process.argv.slice(2));
const scenarioDirectory = resolve(repo, "game/generated/scenarios");
await mkdir(scenarioDirectory, { recursive: true });
const scenarioPacks = await loadScenarioPacks(scenarioRoots);
for (const pack of scenarioPacks) {
  const resolvedManifest = resolveScenarioManifest(pack);
  const scenario = {
    format: "project42.scenario",
    version: 1,
    generatedFrom: "validated scenario pack; do not edit this file by hand",
    documentCount: pack.documents.length,
    contentHash: `sha256:${createHash("sha256").update(JSON.stringify(resolvedManifest)).digest("hex")}`,
    scenario: resolvedManifest
  };
  await writeFile(resolve(scenarioDirectory, `${pack.manifest.id}.json`), `${JSON.stringify(scenario, null, 2)}\n`, "utf8");
  console.log(`Built scenario ${pack.manifest.id} with ${pack.documents.length} embedded documents (${scenario.contentHash}).`);
}
